window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8d0c95daf747c74c"]={"versions": [{"id": "FIG-8d0c95daf747c74c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden-Aktivitätsdiagramm (AUTOSAR Methodology Work Product / Activity View) zur Definition des internen Verhaltens von Basissoftware-Modulen innerhalb des BSW-Entwicklungsprozesses der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>: <code>Basic Software Designer</code> (Akteur/Bearbeiter)</li>\n<li><strong>Aktivität</strong>: <code>Define BSW Behavior</code> (zentraler Prozessschritt)</li>\n<li><strong>Eingangsartefakte</strong>:</li>\n<li><code>BSW Standard Package</code> («input», Kardinalität 0..1, Paket-/Dokumentensymbol oben links)</li>\n<li><code>Basic Software Module Description</code> (abgeschnitten als <code>Basic Soft...</code> dargestellt; «input», Kardinalität 1, Dokumentensymbol unten links)</li>\n<li><strong>Ausgangsartefakt</strong>:</li>\n<li><code>Basic Software Module Internal Behavior</code> («output», Kardinalität 1, Dokumentensymbol rechts)</li>\n<li><strong>Beziehungen</strong>:</li>\n<li><code>Basic Software Designer</code> --(«performs», Zielkardinalität 1)--> <code>Define BSW Behavior</code></li>\n<li><code>BSW Standard Package</code> --(«input»)--> <code>Define BSW Behavior</code></li>\n<li><code>Basic Software Module Description</code> --(«input»)--> <code>Define BSW Behavior</code></li>\n<li><code>Define BSW Behavior</code> --(«output»)--> <code>Basic Software Module Internal Behavior</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>Basic Software Designer</code> führt die Aktivität <code>Define BSW Behavior</code> aus.</li>\n<li>Als obligatorische Eingabe (<code>1</code>) dient die Beschreibung des Basissoftware-Moduls (<code>Basic Software Module Description</code>).</li>\n<li>Optional (<code>0..1</code>) fließt ein standardisiertes Paket (<code>BSW Standard Package</code>) als Vorgabe oder Vorlage ein.</li>\n<li>Als Ergebnis der Aktivität wird genau eine interne Verhaltensbeschreibung (<code>Basic Software Module Internal Behavior</code>, Kardinalität <code>1</code>) erzeugt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität ist essenzieller Bestandteil der AUTOSAR-Methodik zur Spezifikation von BSW-Modulen. Das resultierende <code>Basic Software Module Internal Behavior</code> spezifiziert unter anderem Runnable Entities, Scheduling-Events und Schnittstellenanbindungen an das BSW Scheduler / RTE-Umfeld und bildet die formale Grundlage für die BSW-Konfiguration und Code-Generierung.</p>"}, {"id": "FIG-94d903d1afddaf12", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden-Aktivitätsdiagramm (AUTOSAR Methodology Work Product / Activity View) zur Definition des internen Verhaltens von Basissoftware-Modulen innerhalb des BSW-Entwicklungsprozesses der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>: <code>Basic Software Designer</code> (Akteur/Bearbeiter)</li>\n<li><strong>Aktivität</strong>: <code>Define BSW Behavior</code> (zentraler Prozessschritt)</li>\n<li><strong>Eingangsartefakte</strong>:</li>\n<li><code>BSW Standard Package</code> («input», Kardinalität 0..1, Paket-/Dokumentensymbol oben links)</li>\n<li><code>Basic Software Module Description</code> (abgeschnitten als <code>Basic Soft...</code> dargestellt; «input», Kardinalität 1, Dokumentensymbol unten links)</li>\n<li><strong>Ausgangsartefakt</strong>:</li>\n<li><code>Basic Software Module Internal Behavior</code> («output», Kardinalität 1, Dokumentensymbol rechts)</li>\n<li><strong>Beziehungen</strong>:</li>\n<li><code>Basic Software Designer</code> --(«performs», Zielkardinalität 1)--> <code>Define BSW Behavior</code></li>\n<li><code>BSW Standard Package</code> --(«input»)--> <code>Define BSW Behavior</code></li>\n<li><code>Basic Software Module Description</code> --(«input»)--> <code>Define BSW Behavior</code></li>\n<li><code>Define BSW Behavior</code> --(«output»)--> <code>Basic Software Module Internal Behavior</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>Basic Software Designer</code> führt die Aktivität <code>Define BSW Behavior</code> aus.</li>\n<li>Als obligatorische Eingabe (<code>1</code>) dient die Beschreibung des Basissoftware-Moduls (<code>Basic Software Module Description</code>).</li>\n<li>Optional (<code>0..1</code>) fließt ein standardisiertes Paket (<code>BSW Standard Package</code>) als Vorgabe oder Vorlage ein.</li>\n<li>Als Ergebnis der Aktivität wird genau eine interne Verhaltensbeschreibung (<code>Basic Software Module Internal Behavior</code>, Kardinalität <code>1</code>) erzeugt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität ist essenzieller Bestandteil der AUTOSAR-Methodik zur Spezifikation von BSW-Modulen. Das resultierende <code>Basic Software Module Internal Behavior</code> spezifiziert unter anderem Runnable Entities, Scheduling-Events und Schnittstellenanbindungen an das BSW Scheduler / RTE-Umfeld und bildet die formale Grundlage für die BSW-Konfiguration und Code-Generierung.</p>"}], "trans": [{"from": "FIG-8d0c95daf747c74c", "to": "FIG-94d903d1afddaf12", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
